if(cards.length){const requested=cards.findIndex(c=>c.id===params.get('screen'));selected=requested>=0?requested:0;focus(selected);if(params.get('motion')==='1'&&motionIndices.length){setMotionMode(true);showTV(requested>=0&&cards[requested].video?requested:motionIndices[0])}else if(params.get('present')==='1')showTV(selected)}else{$('present').disabled=true;$('fit').disabled=true;fit(shelfX,shelfY,2180,shelf.offsetHeight);toast('Native captures are still being prepared')}
